-- Accounts are synced in place and never deleted (an account gone is `active = false`).
GRANT SELECT, INSERT, UPDATE ON ledger_account TO cs_runtime;
--> statement-breakpoint
-- Notes are a log: a change is a newer note.
GRANT SELECT, INSERT ON ledger_account_note, booking_line TO cs_runtime;
--> statement-breakpoint
-- Links, the cursor, transactions and rules change in place; nothing deletes them (a rule is
-- turned off, a transaction the bank dropped is `removed`).
GRANT SELECT, INSERT, UPDATE ON bank_account_link, bank_feed_cursor, bank_txn, booking_rule TO cs_runtime;
--> statement-breakpoint
-- A booking is inserted, then only its outcome changes: a changed decision is a new booking.
GRANT SELECT, INSERT, UPDATE ON booking TO cs_runtime;
--> statement-breakpoint
CREATE TRIGGER ledger_account_note_immutable BEFORE UPDATE OR DELETE ON ledger_account_note
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
--> statement-breakpoint
CREATE TRIGGER booking_line_immutable BEFORE UPDATE OR DELETE ON booking_line
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
--> statement-breakpoint
CREATE TRIGGER booking_outcome_only BEFORE UPDATE OR DELETE ON booking
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except(
    'status', 'user_id', 'external_action_id', 'qbo_entity', 'qbo_id', 'error', 'decided_at',
    'posted_at');
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ledger_account', 'ledger_account_note', 'bank_account_link',
      'bank_feed_cursor', 'bank_txn', 'booking_rule', 'booking', 'booking_line'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
  END LOOP;
  -- Which pack owns a table (docs/plan.md §1.12): the chart of accounts is the platform's.
  FOREACH t IN ARRAY ARRAY['bank_account_link', 'bank_feed_cursor', 'bank_txn', 'booking_rule',
      'booking', 'booking_line'] LOOP
    EXECUTE format('COMMENT ON TABLE %I IS %L', t, 'pack:bookkeeping');
  END LOOP;
END
$$;
